#!/usr/bin/env node
'use strict';

/**
 * Generates a randomized directory/file tree for testing the backup/split/recover flow, plus a manifest.json
 * (relative path -> size + sha256 for every generated file) so a later recovery/merge result can be verified
 * automatically by diffing hashes, instead of by eye.
 *
 * Safety model (see lib/safety.js for the implementation):
 *  - Every write happens under a single `root` folder that is validated by resolveSafeRoot (no drive roots, no
 *    home/Desktop/Documents/Downloads/etc, no top-level system folders, and must be nested >= 2 levels deep).
 *  - The root is "owned" via a marker file. --reset only ever clears a root that already carries that marker -
 *    it will refuse to touch a pre-existing folder that isn't one of its own.
 *  - Nothing outside `root` (and the sibling manifest file next to it) is ever written to or deleted.
 *
 * Nothing generated by this script (or any other test-harness script) is ever written to the OS temp directory,
 * AppData, or anywhere else outside this project - see lib/fixtures-root.js. Everything lands under
 * test-harness/generated-fixtures/ (git-ignored), so it's always somewhere you already know to look, and safe
 * to delete by hand at any time.
 *
 * Usage:
 *   node test-harness/generate-random-tree.js [options]
 *
 * Options (all optional):
 *   --root <path>            Where to generate the tree. Default: a fresh timestamped folder under
 *                            test-harness/generated-fixtures/ (see lib/fixtures-root.js).
 *   --reset                  Clear out an existing --root before generating (only if it carries our marker).
 *   --seed <number>          PRNG seed, for a reproducible tree. Default: current timestamp.
 *   --files <number>         Number of "normal" files to generate. Default: 40.
 *   --max-depth <number>     Max subdirectory nesting depth. Default: 4.
 *   --min-size <bytes>       Minimum file size. Default: 0.
 *   --max-size <bytes>       Maximum file size. Default: 2000000 (2 MB).
 *   --large-file-bytes <n>   Also generate one extra file of exactly this size - use a size bigger than your
 *                            test "disc capacity" to exercise the split-large-files path.
 *   --disk-capacity-bytes <n> Purely informational - recorded in manifest.json so you can cross-check against
 *                            whatever capacity you select in the app's UI. Does not affect generation size
 *                            distribution.
 *   --no-edge-cases          Skip the built-in edge cases (zero-byte file, unicode/space filename, empty dir).
 *
 * Example:
 *   node test-harness/generate-random-tree.js --root "test-harness/generated-fixtures/run1" ^
 *     --files 60 --max-size 5000000 --disk-capacity-bytes 700000000 --large-file-bytes 900000000
 */

const fs = require('fs');
const path = require('path');
const { resolveSafeRoot, clearMarkedRootContents, writeOwnershipMarker } = require('./lib/safety');
const { writeRandomFile } = require('./lib/random-file-writer');
const { FIXTURES_ROOT } = require('./lib/fixtures-root');

function parseArgs(argv) {
  const args = { reset: false, edgeCases: true };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    switch (a) {
      case '--root': args.root = argv[++i]; break;
      case '--reset': args.reset = true; break;
      case '--seed': args.seed = Number(argv[++i]); break;
      case '--files': args.files = Number(argv[++i]); break;
      case '--max-depth': args.maxDepth = Number(argv[++i]); break;
      case '--min-size': args.minSize = Number(argv[++i]); break;
      case '--max-size': args.maxSize = Number(argv[++i]); break;
      case '--large-file-bytes': args.largeFileBytes = Number(argv[++i]); break;
      case '--disk-capacity-bytes': args.diskCapacityBytes = Number(argv[++i]); break;
      case '--no-edge-cases': args.edgeCases = false; break;
      case '--help': case '-h': args.help = true; break;
      default:
        throw new Error(`Unknown argument: ${a} (run with --help)`);
    }
  }
  return args;
}

function printHelp() {
  console.log(fs.readFileSync(__filename, 'utf8').split('\n').slice(1, 42).join('\n'));
}

// mulberry32 - small, fast, dependency-free seeded PRNG. Deterministic given the same seed.
function makePrng(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const WORD_PARTS = ['alpha', 'bravo', 'cedar', 'delta', 'ember', 'fjord', 'grove', 'harbor', 'ionic', 'joule', 'karst', 'lumen', 'mango', 'nadir', 'onyx', 'pivot', 'quartz', 'raven', 'sable', 'talon'];
const EXTENSIONS = ['.txt', '.dat', '.bin', '.log', '.csv', '.md', '.jpg', '.pdf'];

function randInt(rnd, min, max) {
  return Math.floor(min + rnd() * (max - min + 1));
}

function randomName(rnd, withExt = true) {
  const parts = randInt(rnd, 1, 3);
  let name = '';
  for (let i = 0; i < parts; i++) {
    name += (i > 0 ? '-' : '') + WORD_PARTS[randInt(rnd, 0, WORD_PARTS.length - 1)];
  }
  name += '-' + randInt(rnd, 1000, 9999);
  return withExt ? name + EXTENSIONS[randInt(rnd, 0, EXTENSIONS.length - 1)] : name;
}

function ensureDir(p) {
  fs.mkdirSync(p, { recursive: true });
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) { printHelp(); return; }

  const seed = Number.isFinite(args.seed) ? args.seed : Date.now();
  const rnd = makePrng(seed);

  const fileCount = Number.isFinite(args.files) ? args.files : 40;
  const maxDepth = Number.isFinite(args.maxDepth) ? args.maxDepth : 4;
  const minSize = Number.isFinite(args.minSize) ? args.minSize : 0;
  const maxSize = Number.isFinite(args.maxSize) ? args.maxSize : 2_000_000;
  const edgeCases = args.edgeCases;

  const defaultRoot = path.join(FIXTURES_ROOT, `run-${Date.now()}`);
  const root = resolveSafeRoot(args.root || defaultRoot);

  if (args.reset) {
    clearMarkedRootContents(root);
  }
  writeOwnershipMarker(root);

  console.log(`Generating random test tree under:\n  ${root}\n(seed=${seed}, files=${fileCount}, maxDepth=${maxDepth}, size=[${minSize},${maxSize}] bytes)`);

  // Track known subdirectories (relative to root) to randomly reuse or extend.
  const dirs = [''];
  const manifestFiles = [];
  let totalBytes = 0;

  function pickOrGrowDir() {
    const base = dirs[randInt(rnd, 0, dirs.length - 1)];
    const baseDepth = base === '' ? 0 : base.split(path.sep).length;
    // ~50% chance to descend one more level, capped at maxDepth.
    if (baseDepth < maxDepth && rnd() < 0.5) {
      const newDir = path.join(base, randomName(rnd, false));
      dirs.push(newDir);
      return newDir;
    }
    return base;
  }

  for (let i = 0; i < fileCount; i++) {
    const dirRel = pickOrGrowDir();
    ensureDir(path.join(root, dirRel));
    const relPath = path.join(dirRel, randomName(rnd));
    const size = randInt(rnd, minSize, maxSize);
    const sha256 = writeRandomFile(path.join(root, relPath), size);
    manifestFiles.push({ relativePath: relPath.split(path.sep).join('/'), sizeBytes: size, sha256 });
    totalBytes += size;
  }

  if (edgeCases) {
    // Zero-byte file.
    const zeroRel = path.join('edge-cases', 'zero-byte-file.dat');
    ensureDir(path.join(root, 'edge-cases'));
    const zeroHash = writeRandomFile(path.join(root, zeroRel), 0);
    manifestFiles.push({ relativePath: zeroRel.split(path.sep).join('/'), sizeBytes: 0, sha256: zeroHash });

    // Unicode / space-containing filename.
    const unicodeRel = path.join('edge-cases', 'αρχείο δοκιμής ünïcödé 测试 📀.txt');
    const uSize = randInt(rnd, 1, 4096);
    const uHash = writeRandomFile(path.join(root, unicodeRel), uSize);
    manifestFiles.push({ relativePath: unicodeRel.split(path.sep).join('/'), sizeBytes: uSize, sha256: uHash });
    totalBytes += uSize;

    // Empty directory (no files inside it at all).
    ensureDir(path.join(root, 'edge-cases', 'empty-directory'));
  }

  if (Number.isFinite(args.largeFileBytes) && args.largeFileBytes > 0) {
    const largeRel = path.join('large-files', 'oversized-file.bin');
    ensureDir(path.join(root, 'large-files'));
    console.log(`Writing large file (${args.largeFileBytes.toLocaleString()} bytes) - this may take a bit...`);
    const largeHash = writeRandomFile(path.join(root, largeRel), args.largeFileBytes);
    manifestFiles.push({ relativePath: largeRel.split(path.sep).join('/'), sizeBytes: args.largeFileBytes, sha256: largeHash });
    totalBytes += args.largeFileBytes;
  }

  manifestFiles.sort((a, b) => a.relativePath.localeCompare(b.relativePath));

  const manifest = {
    tool: 'optical-backup-test-harness/generate-random-tree',
    generatedAt: new Date().toISOString(),
    seed,
    root,
    diskCapacityBytes: Number.isFinite(args.diskCapacityBytes) ? args.diskCapacityBytes : null,
    fileCount: manifestFiles.length,
    totalSizeBytes: totalBytes,
    files: manifestFiles,
  };

  // Written NEXT TO root (not inside it) so the generated tree stays a "pure" fixture identical to what a real
  // user's source folder would look like - no foreign manifest file mixed into what the app will back up.
  const manifestPath = `${root}.manifest.json`;
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));

  console.log(`\nDone.`);
  console.log(`  Files generated : ${manifest.fileCount}`);
  console.log(`  Total size      : ${totalBytes.toLocaleString()} bytes`);
  console.log(`  Tree root       : ${root}`);
  console.log(`  Manifest        : ${manifestPath}`);
  console.log(`\nPoint the app's "source" folder at the tree root above. After a backup/recover/merge round trip,`);
  console.log(`verify the result with:\n  node test-harness/verify-manifest.js --manifest "${manifestPath}" --dir "<recovered folder>"`);
}

main();
